import { legacyStockEnd, legacyStockStart, spliceText, withMachineGcode } from "./machine-gcode.ts";

let failed = 0;

function eq(name: string, got: unknown, want: unknown): void {
  const a = JSON.stringify(got);
  const b = JSON.stringify(want);
  if (a === b) return;
  failed += 1;
  console.error(`FAIL ${name}\n  got  ${a}\n  want ${b}`);
}

const engine = [
  "; generated by Lime Slice — FDM strategy blender",
  "; printer: Lime 220",
  "; features: seam blend",
  "M140 S60",
  "M104 S200",
  "M190 S60",
  "M109 S200",
  "G21",
  "G90",
  "M82",
  "G28",
  "G92 E0",
  "M106 S0",
  ";LAYER:0 Z:0.200",
  "G1 X10 Y10 E0.1",
  "G1 Z10.200 F600",
  "M106 S0",
  "M104 S0",
  "M140 S0",
  "; bed 220x220 mm nozzle 0.40 mm",
  "; TIME:10.0s FILAMENT_MM:1.00 FILAMENT_G:0.003 ARCS:0",
  "M84",
  "",
].join("\n");

eq("blank text is the same bytes", withMachineGcode(engine, "", "  \n"), engine);
eq("a stock comment is blank", spliceText(legacyStockStart("Lime 220"), legacyStockStart("Lime 220")), "");
eq("a stock end comment is blank", spliceText(legacyStockEnd("Lime 220"), legacyStockEnd("Lime 220")), "");
eq("user text is kept", spliceText("G28 W ; home", legacyStockStart("Lime 220")), "G28 W ; home");

const wrapped = withMachineGcode(
  engine,
  spliceText("G4 P100 ; settle", legacyStockStart("Lime 220")),
  spliceText("M107 ; fan off", legacyStockEnd("Lime 220")),
);
// A vendor start purges and probes: it must run hot and after the engine's
// G28, and the engine must take back temperatures, modes and E after it.
eq(
  "start runs after heating and homing, and the engine restores its state",
  wrapped.includes(
    "M109 S200\nG21\nG90\nM82\nG28\nG92 E0\nG4 P100 ; settle\n" +
      "M140 S60\nM104 S200\nM190 S60\nM109 S200\nG90\nM82\nG92 E0\nM106 S0\n",
  ),
  true,
);
eq("the engine homes once before the start block", wrapped.indexOf("G28\n") < wrapped.indexOf("G4 P100"), true);
const purge = withMachineGcode(engine, "M83\nG1 X60 E9 F1000 ; purge", "");
eq(
  "E is zeroed and absolute after a relative purge",
  purge.includes("E9 F1000 ; purge\nM140 S60\nM104 S200\nM190 S60\nM109 S200\nG90\nM82\nG92 E0\n"),
  true,
);
eq(
  "a file that never homes takes the start after its comments",
  withMachineGcode("; head\nG1 X1\n", "G4 P1", ""),
  "; head\nG4 P1\nG90\nM82\nG92 E0\nG1 X1\n",
);
eq("end sits before the cooldown", wrapped.includes("M107 ; fan off\nM106 S0\nM104 S0\nM140 S0\n"), true);
eq("the engine homing line stays", wrapped.includes("G28\n"), true);
eq("a file with no cooldown appends the end", withMachineGcode("G1 X1\n", "", "M84 ; done"), "G1 X1\nM84 ; done\n");
eq("whitespace-only start does not move the file", withMachineGcode(engine, " \n\t", ""), engine);

// A printer whose start block owns heating and homing (Klipper PRINT_START).
const beltEngine = [
  "; generated by Lime Slice — FDM strategy blender",
  "; printer: Ideaformer IR3 V2",
  "M140 S90",
  "M104 S250",
  "M190 S90",
  "M109 S250",
  "; estimator: lookahead junction_deviation=0.0200",
  "G21",
  "G90",
  "M82",
  "G28",
  "G92 E0",
  "M106 S0",
  ";LAYER:0 Z:0.283",
  "G1 X115.000 Y0.100 F18000",
  "G1 Z200.000 F600",
  "M106 S0",
  "M104 S0",
  "M140 S0",
  "M84",
  "",
].join("\n");
const irStart = "PRINT_START\nM140 S{bed}\nM104 S{nozzle}\nM109 S{nozzle}\nG28 Y\nM82";
const owned = withMachineGcode(beltEngine, irStart, "PRINT_END", { startOwnsHoming: true, heat: { bedC: 90, nozzleC: 250 }, notes: [] });
eq(
  "an owning start block comes first and the engine heat and G28 lines are gone",
  owned.split("\n").slice(0, 24),
  [
    "; generated by Lime Slice — FDM strategy blender",
    "; printer: Ideaformer IR3 V2",
    "PRINT_START",
    "M140 S90",
    "M104 S250",
    "M109 S250",
    "G28 Y",
    "M82",
    "M140 S90",
    "M104 S250",
    "M190 S90",
    "M109 S250",
    "G90",
    "M82",
    "G92 E0",
    "; estimator: lookahead junction_deviation=0.0200",
    "G21",
    "M106 S0",
    ";LAYER:0 Z:0.283",
    "G1 X115.000 Y0.100 F18000",
    "G1 Z200.000 F600",
    "PRINT_END",
    "M106 S0",
    "M104 S0",
  ],
);
eq("no bare G28 survives", owned.split("\n").includes("G28"), false);
eq("placeholders are replaced", owned.includes("{bed}") || owned.includes("{nozzle}"), false);
const capped = withMachineGcode(beltEngine, "", "", { startOwnsHoming: true, heat: { bedC: 90, nozzleC: 250 }, notes: ["; bed capped at 90 C (filament 100 C)"] });
eq(
  "a cap note sits after the comment header, even with no start block",
  capped.split("\n").slice(0, 4),
  ["; generated by Lime Slice — FDM strategy blender", "; printer: Ideaformer IR3 V2", "; bed capped at 90 C (filament 100 C)", "M140 S90"],
);
eq("without a start block the engine file keeps its own homing", capped.replace("; bed capped at 90 C (filament 100 C)\n", ""), beltEngine);
const unowned = withMachineGcode(engine, "G4 P100 ; settle", "", { startOwnsHoming: false, heat: { bedC: 60, nozzleC: 200 }, notes: [] });
eq("flag off is today's bytes", unowned, withMachineGcode(engine, "G4 P100 ; settle", ""));
eq("flag off, no text, no notes is the engine bytes", withMachineGcode(engine, "", "", { startOwnsHoming: false, heat: { bedC: 60, nozzleC: 200 }, notes: [] }), engine);
eq(
  "placeholders are replaced with the flag off too",
  withMachineGcode(engine, "M104 S{nozzle}\nM140 S{bed}", "", { heat: { bedC: 60, nozzleC: 200 } }).includes("G92 E0\nM104 S200\nM140 S60\nM140 S60\n"),
  true,
);
eq("an owning start block on a file that never homes goes after the header", withMachineGcode("; head\nG1 X1\n", "PRINT_START", "", { startOwnsHoming: true }), "; head\nPRINT_START\nG90\nM82\nG92 E0\nG1 X1\n");

if (failed > 0) {
  console.error(`${failed} failed`);
  throw new Error(`${failed} failed`);
}
console.log("machine-gcode: splice ok");
